function n(t){return Math.sqrt(2*t.gravityUp*t.jumpHeight)}function a(t){let r=t.gravityUp*t.fallGravityMultiplier;return Math.sqrt(2*t.jumpHeight/t.gravityUp)+Math.sqrt(2*t.jumpHeight/r)}function u(t,r){let i=n(t),e=Math.min(Math.max(r,0),t.jumpHeight);return(i-Math.sqrt(Math.max(0,i*i-2*t.gravityUp*e)))/t.gravityUp}function m(t,r){if(r>=t.jumpHeight)return 0;let i=t.jumpHeight-Math.max(r,0),e=t.gravityUp*t.fallGravityMultiplier;return Math.sqrt(2*i/t.gravityUp)+Math.sqrt(2*i/e)}export{u as i,m as n,n as r,a as t};